#include <assert.h>
#include "../linux/documents.h"
static void values(Engine *e,const int *expected,int n){assert(e->population_count==n);for(int i=0;i<n;i++)assert(life_population_sample(e,i)==expected[i]);}
#define VALUES(e,...) do{int expected[]={__VA_ARGS__};values(e,expected,(int)(sizeof(expected)/sizeof(expected[0])));}while(0)
int main(void){Engine e;life_init(&e);life_clear(&e);for(int x=1;x<=3;x++)life_set(&e,x,1,1);life_set(&e,9,9,1);VALUES(&e,4);life_step(&e,1);VALUES(&e,4,3);life_checkpoint(&e);life_set(&e,20,20,1);VALUES(&e,4,4);life_step(&e,1);VALUES(&e,4,4,3);life_undo(&e);VALUES(&e,4,4);life_undo(&e);VALUES(&e,4,3);life_redo(&e);VALUES(&e,4,4);life_redo(&e);VALUES(&e,4,4,3);life_back(&e);VALUES(&e,4,4);life_restart(&e);VALUES(&e,4);life_clear(&e);VALUES(&e,0);life_undo(&e);VALUES(&e,4);life_clear(&e);for(int i=0;i<2100;i++)life_step(&e,0);assert(e.population_count==LIFE_POPULATION_LIMIT);for(int i=0;i<e.population_count;i++)assert(life_population_sample(&e,i)==0);Engine copy;life_init(&copy);gchar *text=life_json(&e);GError *error=NULL;assert(life_load_json(&copy,text,&error));assert(copy.population_count==LIFE_POPULATION_LIMIT);g_free(text);e.population_count=3;e.population_history[0]=9;e.population_history[1]=7;e.population_history[2]=0;text=life_json(&e);assert(life_load_json(&copy,text,&error));VALUES(&copy,9,7,0);JsonParser *parser=json_parser_new();assert(json_parser_load_from_data(parser,text,-1,NULL));json_object_remove_member(json_node_get_object(json_parser_get_root(parser)),"population_history");JsonGenerator *generator=json_generator_new();json_generator_set_root(generator,json_parser_get_root(parser));gchar *legacy=json_generator_to_data(generator,NULL);assert(life_documents_match(text,legacy));life_set(&e,20,20,1);gchar *edited=life_json(&e);assert(!life_documents_match(edited,legacy));g_free(edited);g_free(legacy);g_object_unref(generator);g_object_unref(parser);g_free(text);life_destroy(&copy);life_destroy(&e);puts("C population graph: edits, Step, Back, Undo/Redo, reset, 2048 bound and v2 field roundtrip passed.");return 0;}
